export default function CountdownTimer() {
  const [seconds, setSeconds] = useState(3);

  useEffect(() => {
    if (seconds === 0) return;
    const timer = setInterval(() => {
      setSeconds(value => Math.max(0, value - 1));
    }, 1000);
    return () => clearInterval(timer);
  }, [seconds]);

  return <p>{seconds === 0 ? 'Done!' : `Time: ${seconds}`}</p>;
}

