  const [category, setCategory] = useState('All');
  const products = [
    { name: 'React Guide', category: 'Books' },
    { name: 'Keyboard', category: 'Tech' },
    { name: 'JS Handbook', category: 'Books' }
  ];
  const visible = category === 'All'
    ? products
    : products.filter(product => product.category === category);

  return (
    <div>
      {['All', 'Books', 'Tech'].map(item => (
        <button key={item} onClick={() => setCategory(item)}>{item}</button>
      ))}
      <ul>
        {visible.map(product => <li key={product.name}>{product.name}</li>)}
      </ul>
    </div>
  );
}

import { useEffect, useState } from 'react';

export default function DisplayPreference() {
  const [mode, setMode] = useState(() =>
    localStorage.getItem('display-mode') || 'comfortable'
  );

  useEffect(() => {
    localStorage.setItem('display-mode', mode);
  }, [mode]);

  return (
    <div>
      <button onClick={() => setMode('comfortable')}>Comfortable</button>
      <button onClick={() => setMode('compact')}>Compact</button>
      <p>Mode: {mode}</p>
    </div>
  );
}

import { useState } from 'react';

function Modal({ open, onClose }) {
  if (!open) return null;

  return (
    <div role='dialog'>
      <h2>Details</h2>
      <p>This is reusable modal content.</p>
      <button onClick={onClose}>Close</button>
    </div>
  );
}

export default function ModalExample() {
  const [open, setOpen] = useState(false);

  return (
    <div>
      <button onClick={() => setOpen(true)}>Open Details</button>
      <Modal open={open} onClose={() => setOpen(false)} />
    </div>
  );
}

import { useState } from 'react';

function useToggle(initial = false) {
  const [value, setValue] = useState(initial);
  const toggle = () => setValue(current => !current);
  return [value, toggle];
}

export default function TogglePanel() {
  const [open, toggle] = useToggle(false);

  return (
    <div>
      <button onClick={toggle}>{open ? 'Hide' : 'Show'}</button>
      {open && <p>Panel content is visible.</p>}
    </div>
  );
}

import { useReducer } from 'react';

function reducer(state, action) {
  if (action.type === 'increment') return state + 1;
  if (action.type === 'decrement') return state - 1;
  if (action.type === 'reset') return 0;
  return state;
}

export default function ReducerCounter() {
  const [count, dispatch] = useReducer(reducer, 0);

  return (
    <div>
      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
      <span>{count}</span>
      <button onClick={() => dispatch({ type: 'increment' })}>+</button>
      <button onClick={() => dispatch({ type: 'reset' })}>Reset</button>
    </div>
  );
}

