import { useMemo, useState } from 'react';

export default function MemoizedFilter() {
  const [search, setSearch] = useState('');
  const products = ['Phone', 'Laptop', 'Headphones', 'Monitor'];

  const filtered = useMemo(() => {
    return products.filter(product =>
      product.toLowerCase().includes(search.toLowerCase())
    );
  }, [search]);

  return (
    <div>
      <input value={search} onChange={e => setSearch(e.target.value)} />
      <ul>
        {filtered.map(product => <li key={product}>{product}</li>)}
      </ul>
    </div>
  );
}

import { useEffect, useState } from 'react';

export default function DebouncedSearch() {
  const [query, setQuery] = useState('');
  const [debounced, setDebounced] = useState('');

  useEffect(() => {
    const timer = setTimeout(() => setDebounced(query), 500);
    return () => clearTimeout(timer);
  }, [query]);

  return (
    <div>
      <input
        value={query}
        onChange={e => setQuery(e.target.value)}
        placeholder='Search'
      />
      <p>Searching for: {debounced}</p>
    </div>
  );
}

import { useState } from 'react';

export default function PaginatedList() {
  const [page, setPage] = useState(1);
  const products = ['Phone', 'Laptop', 'Monitor', 'Keyboard', 'Mouse', 'Tablet'];
  const perPage = 2;
  const totalPages = Math.ceil(products.length / perPage);
  const visible = products.slice((page - 1) * perPage, page * perPage);

  return (
    <div>
      <ul>
        {visible.map(product => <li key={product}>{product}</li>)}
      </ul>
      <button disabled={page === 1} onClick={() => setPage(page - 1)}>
        Previous
      </button>
      <span> Page {page} of {totalPages} </span>
      <button disabled={page === totalPages} onClick={() => setPage(page + 1)}>
        Next
      </button>
    </div>
  );
}

import { useMemo, useState } from 'react';

export default function SortableList() {
  const [ascending, setAscending] = useState(true);
  const products = ['Phone', 'Apple', 'Laptop', 'Monitor'];

  const sorted = useMemo(() => {
    return [...products].sort((a, b) =>
      ascending ? a.localeCompare(b) : b.localeCompare(a)
    );
  }, [ascending]);

  return (
    <div>
      <button onClick={() => setAscending(current => !current)}>
        Sort {ascending ? 'Descending' : 'Ascending'}
      </button>
      <ul>
        {sorted.map(product => <li key={product}>{product}</li>)}
      </ul>
    </div>
  );
}

import { useState } from 'react';

export default function RegistrationForm() {
  const [form, setForm] = useState({ name: '', email: '' });
  const [submitted, setSubmitted] = useState(null);

  function handleChange(e) {
    setForm(current => ({ ...current, [e.target.name]: e.target.value }));
  }

  function handleSubmit(e) {
    e.preventDefault();
    setSubmitted(form);
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input name='name' value={form.name} onChange={handleChange} />
        <input name='email' value={form.email} onChange={handleChange} />
        <button type='submit'>Register</button>
      </form>
      {submitted && (
        <p>{submitted.name} - {submitted.email}</p>
      )}
    </div>
  );
}

function DataTable({ columns, rows }) {
  return (
    <table>
      <thead>
        <tr>
          {columns.map(column => <th key={column.key}>{column.label}</th>)}
        </tr>
      </thead>
      <tbody>
        {rows.map(row => (
          <tr key={row.id}>
            {columns.map(column => (
              <td key={column.key}>{row[column.key]}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

