import { useEffect, useState } from 'react';

export default function DataBox() {
  const [data, setData] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    fetch('/api/data').then(response => response.json()).then(setData).catch(() => setError(true));
  }, []);

  if (error) return <p>Unable to load</p>;
  if (!data) return <p>Loading...</p>;
  return <p>{data.name}</p>;
}

import { useEffect, useState } from 'react';

export default function UserData() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    fetch('/api/user', { signal: controller.signal }).then(r => r.json()).then(setUser).catch(() => {});
    return () => controller.abort();
  }, []);

  return <p>{user ? user.name : 'Loading...'}</p>;
}

import { useState } from 'react';

export default function DynamicForm() {
  const [fields, setFields] = useState(['']);
  const update = (index, value) => setFields(fields.map((item, i) => i === index ? value : item));
  const add = () => setFields([...fields, '']);
  const remove = index => setFields(fields.filter((_, i) => i !== index));

  return <div>{fields.map((field, i) => <div key={i}><input value={field} onChange={e => update(i, e.target.value)} /><button onClick={() => remove(i)}>Remove</button></div>)}<button onClick={add}>Add</button></div>;
}

import { useState } from 'react';

export default function SelectList() {
  const items = ['A', 'B', 'C'];
  const [selected, setSelected] = useState([]);
  const all = selected.length === items.length;
  const toggle = item => setSelected(selected.includes(item) ? selected.filter(x => x !== item) : [...selected, item]);

  return <div><label><input type={'checkbox'} checked={all} onChange={() => setSelected(all ? [] : items)} />Select all</label>{items.map(item => <label key={item}><input type={'checkbox'} checked={selected.includes(item)} onChange={() => toggle(item)} />{item}</label>)}</div>;
}

import { useMemo, useState } from 'react';

export default function SortList() {
  const [ascending, setAscending] = useState(true);
  const items = [3, 1, 2];
  const sorted = useMemo(() => [...items].sort((a, b) => ascending ? a - b : b - a), [ascending]);

  return <div><button onClick={() => setAscending(!ascending)}>Reverse</button><ul>{sorted.map(item => <li key={item}>{item}</li>)}</ul></div>;
}

import { useState } from 'react';

export default function Pager() {
  const items = ['A', 'B', 'C', 'D', 'E'];
  const size = 2;
  const [page, setPage] = useState(0);
  const visible = items.slice(page * size, page * size + size);
  const last = Math.ceil(items.length / size) - 1;

  return <div><ul>{visible.map(item => <li key={item}>{item}</li>)}</ul><button disabled={page === 0} onClick={() => setPage(page - 1)}>Prev</button><button disabled={page === last} onClick={() => setPage(page + 1)}>Next</button></div>;
}

import { useEffect, useState } from 'react';

export default function Modal() {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    if (!open) return;
    const close = e => e.key === 'Escape' && setOpen(false);
    window.addEventListener('keydown', close);
    return () => window.removeEventListener('keydown', close);
  }, [open]);

  return <div><button onClick={() => setOpen(true)}>Open</button>{open && <div role={'dialog'}><p>Modal content</p><button onClick={() => setOpen(false)}>Close</button></div>}</div>;
}

import { useEffect, useRef, useState } from 'react';

export default function Panel() {
  const [open, setOpen] = useState(false);
  const panel = useRef(null);

  useEffect(() => {
    if (!open) return;
    const close = e => !panel.current?.contains(e.target) && setOpen(false);
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [open]);

  return <div><button onClick={() => setOpen(true)}>Open</button>{open && <section ref={panel}><p>Panel</p></section>}</div>;
}

import { createContext, useContext, useState } from 'react';

const ThemeContext = createContext();

function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light');
  const toggle = () => setTheme(theme === 'light' ? 'dark' : 'light');
  return <ThemeContext.Provider value={{ theme, toggle }}>{children}</ThemeContext.Provider>;
}

function Button() {
  const { theme, toggle } = useContext(ThemeContext);
  return <button onClick={toggle}>Theme: {theme}</button>;
}

export default function App() {
  return <ThemeProvider><Button /></ThemeProvider>;
}

import { useReducer } from 'react';

function reducer(state, action) {
  return { ...state, [action.name]: action.value };
}

export default function Form() {
  const [form, dispatch] = useReducer(reducer, { name: '', email: '' });
  const change = e => dispatch({ name: e.target.name, value: e.target.value });
  return <form><input name={'name'} value={form.name} onChange={change} /><input name={'email'} value={form.email} onChange={change} /></form>;
}

import { useMemo, useState } from 'react';

export default function Stats() {
  const [values, setValues] = useState([10, 20, 30]);
  const total = useMemo(() => values.reduce((sum, value) => sum + value, 0), [values]);
  const average = values.length ? total / values.length : 0;
  const add = () => setValues([...values, 10]);

  return <div><p>Count: {values.length}</p><p>Total: {total}</p><p>Average: {average}</p><button onClick={add}>Add 10</button></div>;
}

export default function DataList({ items, loading, renderItem }) {
  if (loading) return <p>Loading...</p>;
  if (!items.length) return <p>No items</p>;

  return <ul>{items.map((item, index) => <li key={item.id ?? index}>{renderItem(item)}</li>)}</ul>;
}
